package com.learnagent.quiz; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="answer_records") public class AnswerRecord{@Id private UUID id;@Column(name="quiz_id",nullable=false)private UUID quizId;@Column(name="question_id",nullable=false)private UUID questionId;@Column(name="course_id",nullable=false)private UUID courseId;@Column(name="knowledge_point",nullable=false)private String knowledgePoint;@Column(name="user_answer")private String userAnswer;@Column(nullable=false)private boolean correct;@Column(name="answered_at",nullable=false)private Instant answeredAt;protected AnswerRecord(){}public AnswerRecord(UUID quiz,UUID question,UUID course,String kp,String answer,boolean correct){id=UUID.randomUUID();quizId=quiz;questionId=question;courseId=course;knowledgePoint=kp;userAnswer=answer;this.correct=correct;answeredAt=Instant.now();}public UUID getQuizId(){return quizId;}public UUID getQuestionId(){return questionId;}public UUID getCourseId(){return courseId;}public String getKnowledgePoint(){return knowledgePoint;}public String getUserAnswer(){return userAnswer;}public boolean isCorrect(){return correct;}public Instant getAnsweredAt(){return answeredAt;}}
